from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])

    # The grid-line color is the color appearing most often in any single row or column.
    line_color = None
    best_count = -1
    for row in grid:
        color, count = Counter(row).most_common(1)[0]
        if count > best_count:
            line_color, best_count = color, count
    for c in range(w):
        color, count = Counter(grid[r][c] for r in range(h)).most_common(1)[0]
        if count > best_count:
            line_color, best_count = color, count

    rows = [r for r in range(h)
            if grid[r].count(line_color) >= 0.6 * w]
    cols = [c for c in range(w)
            if sum(grid[r][c] == line_color for r in range(h)) >= 0.6 * h]

    background = Counter(
        value for row in grid for value in row if value != line_color
    ).most_common(1)[0][0]

    out = []
    for i in range(len(rows) - 1):
        out_row = []
        for j in range(len(cols) - 1):
            corners = [
                grid[rows[i]][cols[j]],
                grid[rows[i]][cols[j + 1]],
                grid[rows[i + 1]][cols[j]],
                grid[rows[i + 1]][cols[j + 1]],
            ]
            color = corners[0]
            if color != line_color and color != background and all(
                value == color for value in corners
            ):
                out_row.append(color)
            else:
                out_row.append(background)
        out.append(out_row)
    return out
